      rewriteAssetLinks({
        markdown: `![](a.png)\n\nand again ![](a.png)`,
        assets: [{ sourceLocator: "a.png", url: MIRRORED }],
      }),
    ).toBe(`![](${MIRRORED})\n\nand again ![](${MIRRORED})`);
  });

