  it("labels a non-media link with the recorded name rather than the storage URL", () => {
    const published = `${MIRRORED.replace("/o/x", "/o/GVfB6XBcMR")}`;
    const result = rewriteAssetLinks({
      markdown: `Protocol: ${published}`,
