import { describe, expect, it, vi } from "vitest";
import type { DGSupabaseClient } from "../client";
import { buildSharedNodes, getSharedNodeByRid } from "../sharedNodes";

type BuildArgs = Parameters<typeof buildSharedNodes>[0];

const spaces: BuildArgs["spaces"] = [
  {
    id: 20,
    name: "Research vault",
    platform: "Obsidian",
    url: "obsidian:vault-a",
  },
];
const nodes: BuildArgs["nodes"] = [
  {
    core_title: "REM sleep and recall",
    is_schema: false,
    last_modified: "2026-06-14T12:00:00",
    schema_id: 200,
    source_local_id: "node-1",
    space_id: 20,
    reference_content: {},
    concepts_of_relation: [],
  },
];
const directContents: BuildArgs["directContents"] = [
  {
    author_id: 42,
    created: "2026-06-14T11:00:00",
    last_modified: "2026-06-14T13:00:00",
    metadata: { source: "obsidian" },
    source_local_id: "node-1",
    space_id: 20,
    text: "EVD - REM sleep and recall",
    variant: "direct",
  },
];
const fullContentSummaries: BuildArgs["fullContentSummaries"] = [
  {
    last_modified: "2026-06-14T15:00:00",
    source_local_id: "node-1",
    space_id: 20,
  },
];
const rid = "orn:obsidian.note:vault-a/node-1";

const build = ({
  nodesOverride = nodes,
  directOverride = directContents,
  fullOverride = fullContentSummaries,
  spacesOverride = spaces,
}: {
  nodesOverride?: typeof nodes;
  directOverride?: typeof directContents;
  fullOverride?: typeof fullContentSummaries;
  spacesOverride?: typeof spaces;
} = {}) =>
  buildSharedNodes({
    nodes: nodesOverride,
    directContents: directOverride,
    fullContentSummaries: fullOverride,
    spaces: spacesOverride,
  });

describe("buildSharedNodes", () => {
  it("builds a group-shared contract node with stable source identity", () => {
    expect(build()).toEqual([
      {
        rid,
        sourceLocalId: "node-1",
        schemaId: 200,
        spaceId: 20,
        spaceName: "Research vault",
        spaceUri: "obsidian:vault-a",
        platform: "Obsidian",
        title: "EVD - REM sleep and recall",
        coreTitle: "REM sleep and recall",
        created: "2026-06-14T11:00:00.000Z",
        lastModified: "2026-06-14T15:00:00.000Z",
        authorId: 42,
        directMetadata: { source: "obsidian" },
      },
    ]);
  });

  it("builds a Roam-origin shared node with a URL-based rid", () => {
    const roamSpaces: BuildArgs["spaces"] = [
      {
        id: 30,
        name: "Research graph",
        platform: "Roam",
        url: "https://roamresearch.com/#/app/research-graph",
      },
    ];
    const roamNodes: BuildArgs["nodes"] = [
      {
        ...nodes[0]!,
        core_title: "Sleep improves memory consolidation",
        space_id: 30,
        source_local_id: "roam-uid-1",
      },
    ];
    const roamDirect: BuildArgs["directContents"] = [
      {
        ...directContents[0]!,
        space_id: 30,
        source_local_id: "roam-uid-1",
        metadata: null,
        text: "CLM - Sleep improves memory consolidation",
      },
    ];
    const roamFull: BuildArgs["fullContentSummaries"] = [
      {
        last_modified: "2026-06-14T15:00:00",
        source_local_id: "roam-uid-1",
        space_id: 30,
      },
    ];
    expect(
      build({
        nodesOverride: roamNodes,
        directOverride: roamDirect,
        fullOverride: roamFull,
        spacesOverride: roamSpaces,
      }),
    ).toEqual([
      {
        rid: "https://roamresearch.com/#/app/research-graph/roam-uid-1",
        sourceLocalId: "roam-uid-1",
        schemaId: 200,
        spaceId: 30,
        spaceName: "Research graph",
        spaceUri: "https://roamresearch.com/#/app/research-graph",
        platform: "Roam",
        title: "CLM - Sleep improves memory consolidation",
        coreTitle: "Sleep improves memory consolidation",
        created: "2026-06-14T11:00:00.000Z",
        lastModified: "2026-06-14T15:00:00.000Z",
        authorId: 42,
        directMetadata: null,
      },
    ]);
  });

  it("leaves the core title unset when the source published none", () => {
    expect(
      build({ nodesOverride: [{ ...nodes[0]!, core_title: null }] })[0]
        ?.coreTitle,
    ).toBeUndefined();
  });

  it("discovers a node without full content", () => {
    expect(build({ fullOverride: [] })[0]?.lastModified).toBe(
      "2026-06-14T13:00:00.000Z",
    );
  });

  it("falls back to the direct created date when no last-modified exists", () => {
    expect(
      build({
        nodesOverride: [{ ...nodes[0]!, last_modified: null }],
        directOverride: [{ ...directContents[0]!, last_modified: null }],
        fullOverride: [],
      })[0]?.lastModified,
    ).toBe("2026-06-14T11:00:00.000Z");
  });

  it.each([
    {
      name: "schema concept",
      nodesOverride: [{ ...nodes[0]!, is_schema: true }],
      directOverride: directContents,
    },
    {
      name: "missing node type",
      nodesOverride: [{ ...nodes[0]!, schema_id: null }],
      directOverride: directContents,
    },
    {
      name: "missing direct content",
      nodesOverride: nodes,
      directOverride: [],
    },
  ])("filters a node with $name", ({ nodesOverride, directOverride }) => {
    expect(build({ nodesOverride, directOverride })).toEqual([]);
  });

  it("resolves slots to local ids in the same space and rids elsewhere", () => {
    const otherSpace: BuildArgs["spaces"][number] = {
      id: 21,
      name: "Other vault",
      platform: "Obsidian",
      url: "obsidian:vault-b",
    };
    const nodeWithSlots: BuildArgs["nodes"][number] = {
      ...nodes[0]!,
      reference_content: { evidence: 5, claim: 6, dangling: 7 },
      concepts_of_relation: [
        { id: 5, space_id: 20, source_local_id: "node-5" },
        { id: 6, space_id: 21, source_local_id: "node-6" },
      ],
    };
    expect(
      build({
        nodesOverride: [nodeWithSlots],
        spacesOverride: [...spaces, otherSpace],
      })[0]?.slots,
    ).toEqual({
      evidence: "node-5",
      claim: "orn:obsidian.note:vault-b/node-6",
    });
  });

  it("builds a URL rid without subtype for a slot in a Roam space", () => {
    const roamSpace: BuildArgs["spaces"][number] = {
      id: 22,
      name: "Research graph",
      platform: "Roam",
      url: "https://roamresearch.com/#/app/research-graph",
    };
    const nodeWithRoamSlot: BuildArgs["nodes"][number] = {
      ...nodes[0]!,
      reference_content: { sourceDocument: 8 },
      concepts_of_relation: [
        { id: 8, space_id: 22, source_local_id: "roam-uid-8" },
      ],
    };
    expect(
      build({
        nodesOverride: [nodeWithRoamSlot],
        spacesOverride: [...spaces, roamSpace],
      })[0]?.slots,
    ).toEqual({
      sourceDocument:
        "https://roamresearch.com/#/app/research-graph/roam-uid-8",
    });
  });

  it("sorts newest nodes first", () => {
    const olderNode = {
      ...nodes[0]!,
      last_modified: "2026-06-10T12:00:00",
      source_local_id: "node-2",
    };
    const olderDirect = {
      ...directContents[0]!,
      last_modified: "2026-06-10T12:00:00",
      source_local_id: "node-2",
      text: "Older shared node",
    };
    expect(
      build({
        nodesOverride: [olderNode, nodes[0]!],
        directOverride: [olderDirect, ...directContents],
        fullOverride: fullContentSummaries,
      }).map((node) => node.sourceLocalId),
    ).toEqual(["node-1", "node-2"]);
  });
});

type QueryResult = { data: unknown; error: { message: string } | null };

const makeQueryBuilder = (result: QueryResult) => {
  const builder = {
    select: vi.fn(),
    eq: vi.fn(),
    maybeSingle: vi.fn().mockResolvedValue(result),
    then: (
      resolve: (value: QueryResult) => unknown,
      reject?: (reason: unknown) => unknown,
    ) => Promise.resolve(result).then(resolve, reject),
  };
  builder.select.mockReturnValue(builder);
  builder.eq.mockReturnValue(builder);
  return builder;
};

const makeClient = ({
  space,
  concepts = nodes,
  direct = directContents,
  full = fullContentSummaries,
}: {
  space: BuildArgs["spaces"][number] | null;
  concepts?: BuildArgs["nodes"];
  direct?: BuildArgs["directContents"];
  full?: BuildArgs["fullContentSummaries"];
}) => {
  const spacesBuilder = makeQueryBuilder({ data: space, error: null });
  const conceptsBuilder = makeQueryBuilder({ data: concepts, error: null });
  const makeContentsBuilder = () => {
    let variant = "";
    const builder = {
      select: vi.fn(),
      eq: vi.fn(),
      then: (
        resolve: (value: QueryResult) => unknown,
        reject?: (reason: unknown) => unknown,
      ) =>
        Promise.resolve({
          data: variant === "direct" ? direct : variant === "full" ? full : [],
          error: null,
        }).then(resolve, reject),
    };
    builder.select.mockReturnValue(builder);
    builder.eq.mockImplementation((column: string, value: unknown) => {
      if (column === "variant") variant = value as string;
      return builder;
    });
    return builder;
  };
  const from = vi.fn((table: string) =>
    table === "my_spaces"
      ? spacesBuilder
      : table === "my_concepts"
        ? conceptsBuilder
        : makeContentsBuilder(),
  );
  return {
    client: { from } as unknown as DGSupabaseClient,
    spacesBuilder,
    conceptsBuilder,
  };
};

describe("getSharedNodeByRid", () => {
  it("fetches one shared node by its stored rid", async () => {
    const { client, spacesBuilder, conceptsBuilder } = makeClient({
      space: spaces[0]!,
    });

    await expect(getSharedNodeByRid({ client, rid })).resolves.toEqual({
      rid,
      sourceLocalId: "node-1",
      schemaId: 200,
      spaceId: 20,
      spaceName: "Research vault",
      spaceUri: "obsidian:vault-a",
      platform: "Obsidian",
      title: "EVD - REM sleep and recall",
      coreTitle: "REM sleep and recall",
      created: "2026-06-14T11:00:00.000Z",
      lastModified: "2026-06-14T15:00:00.000Z",
      authorId: 42,
      directMetadata: { source: "obsidian" },
    });
    expect(spacesBuilder.eq).toHaveBeenCalledWith("url", "obsidian:vault-a");
    expect(conceptsBuilder.eq).toHaveBeenCalledWith("space_id", 20);
    expect(conceptsBuilder.eq).toHaveBeenCalledWith(
      "source_local_id",
      "node-1",
    );
  });

  it("queries with the space url and local id parsed from a URL-form rid", async () => {
    const { client, spacesBuilder, conceptsBuilder } = makeClient({
      space: {
        id: 30,
        name: "Research graph",
        platform: "Roam",
        url: "https://roamresearch.com/#/app/research-graph",
      },
      concepts: [],
      direct: [],
      full: [],
    });

    await expect(
      getSharedNodeByRid({
        client,
        rid: "https://roamresearch.com/#/app/research-graph/roam-uid-1",
      }),
    ).resolves.toBeNull();
    expect(spacesBuilder.eq).toHaveBeenCalledWith(
      "url",
      "https://roamresearch.com/#/app/research-graph",
    );
    expect(conceptsBuilder.eq).toHaveBeenCalledWith(
      "source_local_id",
      "roam-uid-1",
    );
  });

  it("returns null when the source space is not visible", async () => {
    const { client } = makeClient({ space: null });

    await expect(getSharedNodeByRid({ client, rid })).resolves.toBeNull();
  });

  it("returns null when the node has no direct content", async () => {
    const { client } = makeClient({ space: spaces[0]!, direct: [] });

    await expect(getSharedNodeByRid({ client, rid })).resolves.toBeNull();
  });

  it("throws when the space lookup fails", async () => {
    const failingBuilder = makeQueryBuilder({
      data: null,
      error: { message: "permission denied" },
    });
    const client = {
      from: vi.fn(() => failingBuilder),
    } as unknown as DGSupabaseClient;

    await expect(getSharedNodeByRid({ client, rid })).rejects.toEqual({
      message: "permission denied",
    });
  });
});

import type { DGSupabaseClient } from "./client";
import { ridToSpaceUriAndLocalId, spaceUriAndLocalIdToRid } from "./rid";
import type { Enums, Json, Tables } from "../dbTypes";

type SharedConcept = Pick<
  Tables<"my_concepts">,
  | "is_schema"
  | "last_modified"
  | "schema_id"
  | "source_local_id"
  | "space_id"
  | "reference_content"
> & {
  core_title: string | null;
  concepts_of_relation: {
    id: number | null;
    space_id: number | null;
    source_local_id: string | null;
  }[];
};
type SharedContent = Pick<
  Tables<"my_contents">,
  | "author_id"
  | "created"
  | "last_modified"
  | "metadata"
  | "source_local_id"
  | "space_id"
  | "text"
  | "variant"
>;
type SharedContentSummary = Pick<
  Tables<"my_contents">,
  "last_modified" | "source_local_id" | "space_id"
>;
type SharedSpace = Pick<
  Tables<"my_spaces">,
  "id" | "name" | "platform" | "url"
>;
type Platform = Enums<"Platform">;

type ValidSharedSpace = {
  name: string;
  platform: Platform;
  url: string;
};

export type SharedNode = {
  rid: string;
  sourceLocalId: string;
  schemaId: number;
  spaceId: number;
  spaceName: string;
  spaceUri: string;
  platform: Platform;
  title: string;
  coreTitle?: string;
  created: string | null;
  lastModified: string;
  authorId?: number;
  directMetadata: Json;
  slots?: Record<string, string>;
};

export type SharedNodeRows = {
  nodes: SharedConcept[];
  directContents: SharedContent[];
  fullContentSummaries: SharedContentSummary[];
  spaces: SharedSpace[];
};

const CONCEPT_COLUMNS_WITH_SLOTS =
  "core_title:literal_content->>core_title, is_schema, last_modified, schema_id, source_local_id, space_id, reference_content, concepts_of_relation(id, space_id, source_local_id)";
const DIRECT_CONTENT_COLUMNS =
  "author_id, created, last_modified, metadata, source_local_id, space_id, text, variant";
const FULL_CONTENT_SUMMARY_COLUMNS = "last_modified, source_local_id, space_id";
const SPACE_COLUMNS = "id, name, platform, url";

const getResourceKey = ({
  sourceLocalId,
  spaceId,
}: {
  sourceLocalId: string;
  spaceId: number;
}): string => `${spaceId}:${sourceLocalId}`;

const normalizeUtcTimestamp = (timestamp: string | null): string | null => {
  if (!timestamp) return null;
  const date = new Date(`${timestamp}Z`);
  return Number.isNaN(date.getTime()) ? null : date.toISOString();
};

const getLatestTimestamp = (timestamps: (string | null)[]): string | null => {
  const validTimestamps = timestamps
    .map(normalizeUtcTimestamp)
    .filter((timestamp): timestamp is string => typeof timestamp === "string");
  if (validTimestamps.length === 0) return null;
  return validTimestamps.reduce((latest, timestamp) =>
    timestamp > latest ? timestamp : latest,
  );
};

export const buildSharedNodes = ({
  nodes,
  directContents,
  fullContentSummaries,
  spaces,
}: SharedNodeRows): SharedNode[] => {
  const spacesById = new Map<number, ValidSharedSpace>(
    spaces.flatMap((space): [number, ValidSharedSpace][] => {
      if (
        typeof space.id !== "number" ||
        typeof space.name !== "string" ||
        space.platform === null ||
        typeof space.url !== "string"
      )
        return [];
      return [
        [
          space.id,
          {
            name: space.name,
            platform: space.platform,
            url: space.url,
          },
        ],
      ];
    }),
  );
  const directByResource = new Map<string, SharedContent>();
  directContents.forEach((content) => {
    if (
      typeof content.space_id !== "number" ||
      typeof content.source_local_id !== "string" ||
      content.variant !== "direct"
    )
      return;
    directByResource.set(
      getResourceKey({
        sourceLocalId: content.source_local_id,
        spaceId: content.space_id,
      }),
      content,
    );
  });

  const fullModifiedByResource = new Map<string, string | null>();
  fullContentSummaries.forEach((summary) => {
    if (
      typeof summary.space_id !== "number" ||
      typeof summary.source_local_id !== "string"
    )
      return;
    fullModifiedByResource.set(
      getResourceKey({
        sourceLocalId: summary.source_local_id,
        spaceId: summary.space_id,
      }),
      summary.last_modified,
    );
  });

  return nodes
    .flatMap((node): SharedNode[] => {
      if (
        node.is_schema !== false ||
        node.schema_id === null ||
        typeof node.space_id !== "number" ||
        typeof node.source_local_id !== "string"
      )
        return [];

      const resourceKey = getResourceKey({
        sourceLocalId: node.source_local_id,
        spaceId: node.space_id,
      });

      const space = spacesById.get(node.space_id);
      const direct = directByResource.get(resourceKey);
      if (!space || typeof direct?.text !== "string") return [];

      const created = normalizeUtcTimestamp(direct.created);
      const lastModified =
        getLatestTimestamp([
          node.last_modified,
          direct.last_modified,
          fullModifiedByResource.get(resourceKey) ?? null,
        ]) ?? created;
      if (!lastModified) return [];

      let rid: string;
      try {
        rid = spaceUriAndLocalIdToRid(space.url, node.source_local_id, "note");
      } catch {
        return [];
      }

      const nodeRidById = Object.fromEntries(
        node.concepts_of_relation
          .filter((c) => c.id !== null)
          .map((c) => {
            if (c.space_id === node.space_id) return [c.id, c.source_local_id];
            const space = spacesById.get(c.space_id || 0);
            if (!space || !c.source_local_id || !c.id) return [c.id, undefined];
            return [
              c.id,
              // To be reviewed if we have relations of relations
              spaceUriAndLocalIdToRid(space.url, c.source_local_id, "note"),
            ];
          }) as [number, string | undefined][],
      );
      const referenceContent = (node.reference_content ?? {}) as Record<
        string,
        number
      >;
      const slots = Object.fromEntries(
        Object.entries(referenceContent ?? {})
          .map(([k, v]) => [k, nodeRidById[v]])
          .filter(([, v]) => v !== undefined) as [string, string][],
      );

      return [
        {
          rid,
          sourceLocalId: node.source_local_id,
          schemaId: node.schema_id,
          spaceId: node.space_id,
          spaceName: space.name,
          spaceUri: space.url,
          platform: space.platform,
          title: direct.text,
          coreTitle: node.core_title ?? undefined,
          created,
          lastModified,
          authorId: direct.author_id ?? undefined,
          directMetadata: direct.metadata,
          slots: Object.keys(slots).length > 0 ? slots : undefined,
        },
      ];
    })
    .sort(
      (left, right) =>
        Date.parse(right.lastModified) - Date.parse(left.lastModified) ||
        left.title.localeCompare(right.title),
    );
};

