      return [
        {
          rid,
          sourceLocalId: node.source_local_id,
          schemaId: node.schema_id,
          spaceId: node.space_id,
          spaceName: space.name,
          spaceUri: space.url,
          platform: space.platform,
          title: direct.text,
          coreTitle: node.core_title ?? undefined,
          created,
          lastModified,
          authorId: direct.author_id ?? undefined,
          directMetadata: direct.metadata,
          slots: Object.keys(slots).length > 0 ? slots : undefined,
        },
      ];
    })
    .sort(
      (left, right) =>
        Date.parse(right.lastModified) - Date.parse(left.lastModified) ||
        left.title.localeCompare(right.title),
    );
};

const getAssociatedSpaces = async ({
  client,
  concepts,
  currentSpace,
  currentSpaceId,
}: {
  client: DGSupabaseClient;
  concepts: SharedConcept[];
  currentSpace?: SharedSpace;
  currentSpaceId?: number;
}): Promise<SharedSpace[]> => {
  const associatedSpaceIds = new Set(
    [
      ...concepts.map((cpt) => cpt.space_id),
      ...concepts.flatMap((cpt) =>
        cpt.concepts_of_relation.map((cr) => cr.space_id),
      ),
    ].filter((id) => id !== null),
  );
  if (currentSpace !== undefined) {
    currentSpaceId = currentSpace.id ?? currentSpaceId;
  } else if (currentSpaceId !== undefined)
    associatedSpaceIds.add(currentSpaceId);
  const spaces: SharedSpace[] = [];
  if (currentSpace !== undefined && currentSpaceId !== undefined) {
    spaces.push(currentSpace);
    associatedSpaceIds.delete(currentSpaceId);
  }
  if (associatedSpaceIds.size > 0) {
    const { data, error } = await client
      .from("my_spaces")
      .select(SPACE_COLUMNS)
      .in("id", [...associatedSpaceIds]);
    if (error) throw error;
    spaces.push(...data);
  }
  return spaces;
};

const getSharedNodeRows = async ({
  client,
  currentSpaceId,
}: {
  client: DGSupabaseClient;
  currentSpaceId: number;
}): Promise<SharedNodeRows> => {
  const [conceptsResponse, directResponse, fullResponse] = await Promise.all([
    client
      .from("my_concepts")
      .select(CONCEPT_COLUMNS_WITH_SLOTS)
      .neq("space_id", currentSpaceId)
      .eq("is_schema", false)
      .eq("is_relation", false),
    client
      .from("my_contents")
      .select(DIRECT_CONTENT_COLUMNS)
      .neq("space_id", currentSpaceId)
      .eq("variant", "direct"),
    client
      .from("my_contents")
      .select(FULL_CONTENT_SUMMARY_COLUMNS)
      .neq("space_id", currentSpaceId)
      .eq("variant", "full"),
  ]);
  if (conceptsResponse.error) throw conceptsResponse.error;
  if (directResponse.error) throw directResponse.error;
  if (fullResponse.error) throw fullResponse.error;
  const spaces = await getAssociatedSpaces({
    client,
    concepts: conceptsResponse.data,
    currentSpaceId,
  });

  return {
    nodes: conceptsResponse.data,
    directContents: directResponse.data,
    fullContentSummaries: fullResponse.data,
    spaces,
  };
};

export const listGroupSharedNodes = async ({
  client,
  currentSpaceId,
}: {
  client: DGSupabaseClient;
  currentSpaceId: number;
}): Promise<SharedNode[]> => {
  const rows = await getSharedNodeRows({ client, currentSpaceId });
  return buildSharedNodes(rows);
};

export const getSharedNodeByRid = async ({
  client,
  rid,
}: {
  client: DGSupabaseClient;
  rid: string;
}): Promise<SharedNode | null> => {
  const { spaceUri, sourceLocalId } = ridToSpaceUriAndLocalId(rid);
  const spaceResponse = await client
    .from("my_spaces")
    .select(SPACE_COLUMNS)
    .eq("url", spaceUri)
    .maybeSingle();
  if (spaceResponse.error) throw spaceResponse.error;
  const space = spaceResponse.data;
  if (!space || typeof space.id !== "number") return null;

  const [conceptsResponse, directResponse, fullResponse] = await Promise.all([
    client
      .from("my_concepts")
      .select(CONCEPT_COLUMNS_WITH_SLOTS)
      .eq("space_id", space.id)
      .eq("source_local_id", sourceLocalId)
      .eq("is_schema", false)
      .eq("is_relation", false),
    client
      .from("my_contents")
      .select(DIRECT_CONTENT_COLUMNS)
      .eq("space_id", space.id)
      .eq("source_local_id", sourceLocalId)
      .eq("variant", "direct"),
    client
      .from("my_contents")
      .select(FULL_CONTENT_SUMMARY_COLUMNS)
      .eq("space_id", space.id)
      .eq("source_local_id", sourceLocalId)
      .eq("variant", "full"),
  ]);
  if (conceptsResponse.error) throw conceptsResponse.error;
  if (directResponse.error) throw directResponse.error;
  if (fullResponse.error) throw fullResponse.error;
  const spaces = await getAssociatedSpaces({
    client,
    concepts: conceptsResponse.data,
    currentSpace: space,
  });

  const [sharedNode] = buildSharedNodes({
    nodes: conceptsResponse.data,
    directContents: directResponse.data,
    fullContentSummaries: fullResponse.data,
    spaces,
  });
  return sharedNode ?? null;
};

import { describe, expect, it, vi } from "vitest";
import type { DGSupabaseClient } from "../client";
import { buildSharedNodes, getSharedNodeByRid } from "../sharedNodes";

type BuildArgs = Parameters<typeof buildSharedNodes>[0];

const spaces: BuildArgs["spaces"] = [
  {
    id: 20,
    name: "Research vault",
    platform: "Obsidian",
    url: "obsidian:vault-a",
  },
];
const nodes: BuildArgs["nodes"] = [
  {
    core_title: "REM sleep and recall",
    is_schema: false,
    last_modified: "2026-06-14T12:00:00",
    schema_id: 200,
    source_local_id: "node-1",
    space_id: 20,
    reference_content: {},
    concepts_of_relation: [],
  },
];
const directContents: BuildArgs["directContents"] = [
  {
    author_id: 42,
    created: "2026-06-14T11:00:00",
    last_modified: "2026-06-14T13:00:00",
    metadata: { source: "obsidian" },
    source_local_id: "node-1",
    space_id: 20,
    text: "EVD - REM sleep and recall",
    variant: "direct",
  },
];
const fullContentSummaries: BuildArgs["fullContentSummaries"] = [
  {
    last_modified: "2026-06-14T15:00:00",
    source_local_id: "node-1",
    space_id: 20,
  },
];
const rid = "orn:obsidian.note:vault-a/node-1";

const build = ({
  nodesOverride = nodes,
  directOverride = directContents,
  fullOverride = fullContentSummaries,
  spacesOverride = spaces,
}: {
  nodesOverride?: typeof nodes;
  directOverride?: typeof directContents;
  fullOverride?: typeof fullContentSummaries;
  spacesOverride?: typeof spaces;
} = {}) =>
  buildSharedNodes({
    nodes: nodesOverride,
    directContents: directOverride,
    fullContentSummaries: fullOverride,
    spaces: spacesOverride,
  });

describe("buildSharedNodes", () => {
  it("builds a group-shared contract node with stable source identity", () => {
    expect(build()).toEqual([
      {
        rid,
        sourceLocalId: "node-1",
        schemaId: 200,
        spaceId: 20,
        spaceName: "Research vault",
        spaceUri: "obsidian:vault-a",
        platform: "Obsidian",
        title: "EVD - REM sleep and recall",
        coreTitle: "REM sleep and recall",
        created: "2026-06-14T11:00:00.000Z",
        lastModified: "2026-06-14T15:00:00.000Z",
        authorId: 42,
        directMetadata: { source: "obsidian" },
      },
    ]);
  });

  it("builds a Roam-origin shared node with a URL-based rid", () => {
    const roamSpaces: BuildArgs["spaces"] = [
      {
        id: 30,
        name: "Research graph",
        platform: "Roam",
        url: "https://roamresearch.com/#/app/research-graph",
      },
    ];
    const roamNodes: BuildArgs["nodes"] = [
      {
        ...nodes[0]!,
        core_title: "Sleep improves memory consolidation",
        space_id: 30,
        source_local_id: "roam-uid-1",
      },
    ];
    const roamDirect: BuildArgs["directContents"] = [
      {
        ...directContents[0]!,
        space_id: 30,
        source_local_id: "roam-uid-1",
        metadata: null,
        text: "CLM - Sleep improves memory consolidation",
      },
    ];
    const roamFull: BuildArgs["fullContentSummaries"] = [
      {
        last_modified: "2026-06-14T15:00:00",
        source_local_id: "roam-uid-1",
        space_id: 30,
      },
    ];
    expect(
      build({
        nodesOverride: roamNodes,
        directOverride: roamDirect,
        fullOverride: roamFull,
        spacesOverride: roamSpaces,
      }),
    ).toEqual([
      {
        rid: "https://roamresearch.com/#/app/research-graph/roam-uid-1",
        sourceLocalId: "roam-uid-1",
        schemaId: 200,
        spaceId: 30,
        spaceName: "Research graph",
        spaceUri: "https://roamresearch.com/#/app/research-graph",
        platform: "Roam",
        title: "CLM - Sleep improves memory consolidation",
        coreTitle: "Sleep improves memory consolidation",
        created: "2026-06-14T11:00:00.000Z",
        lastModified: "2026-06-14T15:00:00.000Z",
        authorId: 42,
        directMetadata: null,
      },
    ]);
  });

  it("leaves the core title unset when the source published none", () => {
    expect(
      build({ nodesOverride: [{ ...nodes[0]!, core_title: null }] })[0]
        ?.coreTitle,
    ).toBeUndefined();
  });

  it("discovers a node without full content", () => {
    expect(build({ fullOverride: [] })[0]?.lastModified).toBe(
      "2026-06-14T13:00:00.000Z",
    );
  });

  it("falls back to the direct created date when no last-modified exists", () => {
    expect(
      build({
        nodesOverride: [{ ...nodes[0]!, last_modified: null }],
        directOverride: [{ ...directContents[0]!, last_modified: null }],
        fullOverride: [],
      })[0]?.lastModified,
    ).toBe("2026-06-14T11:00:00.000Z");
  });

  it.each([
    {
      name: "schema concept",
      nodesOverride: [{ ...nodes[0]!, is_schema: true }],
      directOverride: directContents,
    },
    {
      name: "missing node type",
      nodesOverride: [{ ...nodes[0]!, schema_id: null }],
      directOverride: directContents,
    },
    {
      name: "missing direct content",
      nodesOverride: nodes,
      directOverride: [],
    },
  ])("filters a node with $name", ({ nodesOverride, directOverride }) => {
    expect(build({ nodesOverride, directOverride })).toEqual([]);
  });

  it("resolves slots to local ids in the same space and rids elsewhere", () => {
    const otherSpace: BuildArgs["spaces"][number] = {
      id: 21,
      name: "Other vault",
      platform: "Obsidian",
      url: "obsidian:vault-b",
    };
    const nodeWithSlots: BuildArgs["nodes"][number] = {
      ...nodes[0]!,
      reference_content: { evidence: 5, claim: 6, dangling: 7 },
      concepts_of_relation: [
        { id: 5, space_id: 20, source_local_id: "node-5" },
        { id: 6, space_id: 21, source_local_id: "node-6" },
      ],
    };
    expect(
      build({
        nodesOverride: [nodeWithSlots],
        spacesOverride: [...spaces, otherSpace],
      })[0]?.slots,
    ).toEqual({
      evidence: "node-5",
      claim: "orn:obsidian.note:vault-b/node-6",
    });
  });

  it("builds a URL rid without subtype for a slot in a Roam space", () => {
    const roamSpace: BuildArgs["spaces"][number] = {
      id: 22,
      name: "Research graph",
      platform: "Roam",
      url: "https://roamresearch.com/#/app/research-graph",
    };
    const nodeWithRoamSlot: BuildArgs["nodes"][number] = {
      ...nodes[0]!,
      reference_content: { sourceDocument: 8 },
      concepts_of_relation: [
        { id: 8, space_id: 22, source_local_id: "roam-uid-8" },
      ],
    };
    expect(
      build({
        nodesOverride: [nodeWithRoamSlot],
        spacesOverride: [...spaces, roamSpace],
      })[0]?.slots,
    ).toEqual({
      sourceDocument:
        "https://roamresearch.com/#/app/research-graph/roam-uid-8",
    });
  });

  it("sorts newest nodes first", () => {
    const olderNode = {
      ...nodes[0]!,
      last_modified: "2026-06-10T12:00:00",
      source_local_id: "node-2",
    };
    const olderDirect = {
      ...directContents[0]!,
      last_modified: "2026-06-10T12:00:00",
      source_local_id: "node-2",
      text: "Older shared node",
    };
    expect(
      build({
        nodesOverride: [olderNode, nodes[0]!],
        directOverride: [olderDirect, ...directContents],
        fullOverride: fullContentSummaries,
      }).map((node) => node.sourceLocalId),
    ).toEqual(["node-1", "node-2"]);
  });
});

type QueryResult = { data: unknown; error: { message: string } | null };

